referenceSolutions.javascript:
function digitWorkshopFirstQualifyingSlip(readings, k) {
  const a=readings; let out=[];
  for(let x of a){x=Math.abs(x);let s=0;while(x){s+=x%10;x=Math.floor(x/10);}out.push(s);}
  return out.find(x=>x>=k)??-1;
}

