referenceSolutions.python:
def digitWorkshopFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    for x in a:
        x=abs(x)
        s=0
        while x:
            s+=x%10
            x//=10
        out.append(s)
    return next((x for x in out if x>=k),-1)

